content.content:
[
  {
    "id": "morning-cadence",
    "label": "KeystoneOS morning cadence",
    "taskName": "KeystoneOS Morning",
    "exe": "pwsh",
    "script": "{REPO}/scripts/morning-cadence.ps1",
    "schedule": {
      "kind": "weekdays",
      "at": "06:00"
    },
    "graceMinutes": 45,
    "timeoutMinutes": 30,
    "maxAttemptsPerDay": 3,
    "reconcile": true,
    "successProbe": {
      "kind": "fileContains",
      "path": "{REPO}/outputs/morning/cadence.log",
      "pattern": "/[{DATE}T[^/]]*/] cadence OK"
    }
  }
]

